import { useCallback, useEffect, useState, type FormEvent } from 'react'
import { createExpense, fetchExpenses, ValidationError, type Expense } from './api'

function ExpenseForm({ onCreated }: { onCreated: () => void }) {
  const [label, setLabel] = useState('')
  const [amount, setAmount] = useState('')
  const [currency, setCurrency] = useState('EUR')
  const [errors, setErrors] = useState<Record<string, string>>({})
  const [formError, setFormError] = useState<string | null>(null)
  const [submitting, setSubmitting] = useState(false)

  async function handleSubmit(e: FormEvent) {
    e.preventDefault()
    setSubmitting(true)
    setErrors({})
    setFormError(null)
    try {
      await createExpense({ label, amount: Number(amount), currency })
      setLabel('')
      setAmount('')
      onCreated()
    } catch (err) {
      if (err instanceof ValidationError) {
        setErrors(err.errors)
        const known = ['label', 'amount', 'currency']
        const other = Object.entries(err.errors)
          .filter(([k]) => !known.includes(k))
          .map(([, m]) => m)
        if (other.length) setFormError(other.join(' '))
      } else {
        setFormError(err instanceof Error ? err.message : 'Something went wrong')
      }
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <form onSubmit={handleSubmit} noValidate>
      <h2>New expense</h2>
      <div>
        <label htmlFor="label">Label</label>
        <input
          id="label"
          value={label}
          onChange={(e) => setLabel(e.target.value)}
          aria-invalid={!!errors.label}
          aria-describedby={errors.label ? 'label-error' : undefined}
        />
        {errors.label && <span id="label-error" role="alert">{errors.label}</span>}
      </div>
      <div>
        <label htmlFor="amount">Amount</label>
        <input
          id="amount"
          type="number"
          step="0.01"
          value={amount}
          onChange={(e) => setAmount(e.target.value)}
          aria-invalid={!!errors.amount}
          aria-describedby={errors.amount ? 'amount-error' : undefined}
        />
        {errors.amount && <span id="amount-error" role="alert">{errors.amount}</span>}
      </div>
      <div>
        <label htmlFor="currency">Currency</label>
        <input
          id="currency"
          value={currency}
          onChange={(e) => setCurrency(e.target.value)}
          aria-invalid={!!errors.currency}
          aria-describedby={errors.currency ? 'currency-error' : undefined}
        />
        {errors.currency && <span id="currency-error" role="alert">{errors.currency}</span>}
      </div>
      {formError && <p role="alert">{formError}</p>}
      <button type="submit" disabled={submitting}>
        {submitting ? 'Submitting…' : 'Submit expense'}
      </button>
    </form>
  )
}

export function App() {
  const [expenses, setExpenses] = useState<Expense[] | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [version, setVersion] = useState(0)
  const reload = useCallback(() => setVersion((v) => v + 1), [])

  useEffect(() => {
    const controller = new AbortController()
    fetchExpenses(controller.signal)
      .then((list) => {
        setExpenses(list)
        setError(null)
      })
      .catch((err: unknown) => {
        if (controller.signal.aborted) return
        setError(err instanceof Error ? err.message : 'Failed to load expenses')
      })
    return () => controller.abort()
  }, [version])

  return (
    <main>
      <h1>My expenses</h1>
      {error && <p role="alert">{error}</p>}
      {!expenses && !error && <p>Loading…</p>}
      {expenses && expenses.length === 0 && <p>No expenses yet.</p>}
      {expenses && expenses.length > 0 && (
        <ul>
          {expenses.map((x) => (
            <li key={x.id}>
              {x.label} — {x.amount.toFixed(2)} {x.currency} ({x.status})
            </li>
          ))}
        </ul>
      )}
      <ExpenseForm onCreated={reload} />
    </main>
  )
}
